const items = $input.all();
const GSTIN_REGEX = /^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z]{1}[1-9A-Z]{1}Z[0-9A-Z]{1}$/;

return items.map(item => {
  const data = item.json;
  const gstin = data.gstin || "";
  const formatValid = GSTIN_REGEX.test(gstin);

  let stateCode = null;
  let panFromGstin = null;
  if (formatValid) {
    stateCode = gstin.substring(0, 2);
    panFromGstin = gstin.substring(2, 12);
  }

  return {
    json: {
      ...data,
      format_valid: formatValid,
      derived_pan: panFromGstin,
      state_code: stateCode
    }
  };
});

const items = $input.all();
return items.map(item => {
  const data = item.json;
  const bidderName = (data.bidder_name || "").toUpperCase().trim();
  const record = data.mock_gst_record;
  const issues = [];
  let status = "VERIFIED";
  let confidence = 0.98;
  let riskLevel = "LOW";

  if (!data.format_valid) {
    status = "NOT_VERIFIED";
    confidence = 0.95;
    riskLevel = "HIGH";
    issues.push(`GSTIN format invalid: '${data.gstin}' does not comply with 15-character statutory structure`);
  } else if (!data.mock_record_found) {
    status = "NOT_VERIFIED";
    confidence = 0.90;
    riskLevel = "HIGH";
    issues.push(`GSTIN '${data.gstin}' not found in mock GST registry`);
  } else if (record.status === "CANCELLED") {
    status = "NOT_VERIFIED";
    confidence = 0.96;
    riskLevel = "HIGH";
    issues.push(`GST registration is CANCELLED for taxpayer ${record.legal_name}`);
  } else {
    const regName = record.legal_name.toUpperCase().trim();
    const exactMatch = bidderName === regName;
    const partialMatch = bidderName.includes(regName) || regName.includes(bidderName);

    if (!exactMatch && !partialMatch) {
      status = "REVIEW";
      confidence = 0.60;
      riskLevel = "MEDIUM";
      issues.push(`Name discrepancy: Bidder name '${data.bidder_name}' differs from GST registered name '${record.legal_name}'`);
    } else {
      status = "VERIFIED";
      confidence = 0.98;
      riskLevel = "LOW";
    }
  }

  return {
    json: {
      agent: "GST_AGENT",
      status,
      confidence,
      evidence: {
        gstin: data.gstin,
        legal_name: record ? record.legal_name : null,
        trade_name: record ? record.trade_name : null,
        taxpayer_type: record ? record.taxpayer_type : null,
        registration_status: record ? record.status : "UNREGISTERED",
        state_jurisdiction: record ? record.state_jurisdiction : null,
        center_jurisdiction: record ? record.center_jurisdiction : null,
        filing_compliance: record ? record.filing_status : null,
        derived_pan: data.derived_pan,
        registry_type: "MOCK_GSTN_PORTAL"
      },
      issues,
      risk_level: riskLevel,
      timestamp: new Date().toISOString()
    }
  };
});

